rules_data = cells('W0::Rules', 'B30:D39')
costs_data = cells('W0::Leaf costs', 'E30:F32')
costs = {row[0]: row[1] for row in costs_data}

rules = {}
for p, c, u in rules_data:
    if p not in rules:
        rules[p] = []
    rules[p].append((c, u))

def get_costs(part):
    if part in costs:
        return {part: costs[part]}
    total_leaf_costs = {}
    if part in rules:
        for comp, mult in rules[part]:
            sub = get_costs(comp)
            for leaf, unit_cost in sub.items():
                total_leaf_costs[leaf] = total_leaf_costs.get(leaf, 0) + unit_cost * mult
    return total_leaf_costs

crate_costs = get_costs('Crate')
beacon_costs = get_costs('Beacon')

val_crate = sum(crate_costs.values())
val_beacon = sum(beacon_costs.values())
result = round(val_crate - val_beacon, 2)

